targets.expr:
sum(
  increase(
    envoy_http_downstream_rq_total{
      ai_consumer=~"$ai_consumer",
      cluster=~"$cluster",
      ai_model=~"$ai_model",ai_route=~"ai-route-$ai_route\\.internal"
    }[$__range]
  )
)

histogram_quantile(0.95,
  sum by (ai_model, le) (
    irate(route_upstream_model_consumer_metric_llm_first_token_duration_ms_bucket{ai_consumer=~"$ai_consumer", cluster=~"$cluster", ai_model=~"$ai_model"}[5m])
  )
)

sum by(ai_consumer) (
  increase(
    route_upstream_model_consumer_metric_llm_duration_count{
      ai_consumer=~"(360AI平台-项目开发|API市场|API市场-saas|API市场-效能工程专属)",
      cluster=~"$cluster",
      ai_model=~"$ai_model"
    }[1m]
  )
)

sum by (ai_model) (
  rate(route_upstream_model_consumer_metric_am_llm_duration_count{
    cluster=~"$cluster",ai_model=~"$ai_model"
  }[1m])
)>0

sum by (ai_consumer) (
  rate(route_upstream_model_consumer_metric_am_llm_duration_count{
    cluster=~"$cluster",
    ai_model=~"$ai_model"
  }[1m])
)>0

sum by (ai_model) (
    rate(route_upstream_model_consumer_metric_total_token{
ai_consumer=~"$ai_consumer",cluster=~"$cluster",
      ai_model=~"$ai_model"
    }[1m])
)

sum by (ai_model) (
    rate(route_upstream_model_consumer_metric_output_token{
ai_consumer=~"$ai_consumer",cluster=~"$cluster",
      ai_model=~"$ai_model"
    }[1m])
)

sum by (ai_model) (
    rate(route_upstream_model_consumer_metric_input_token{
ai_consumer=~"$ai_consumer",cluster=~"$cluster",
      ai_model=~"$ai_model"
    }[1m])
)

sum by (ai_model) (
    increase(route_upstream_model_consumer_metric_total_token{
      ai_consumer=~"$ai_consumer",
      cluster=~"$cluster",
      ai_model=~"$ai_model"
    }[$__range])
)

sum by (ai_model) (
  irate(route_upstream_model_consumer_metric_llm_service_duration{
    ai_consumer=~"$ai_consumer",
    cluster=~"$cluster",
    ai_model=~"$ai_model"
  }[2m])
)
/
sum by (ai_model) (
  irate(route_upstream_model_consumer_metric_llm_duration_count{
    ai_consumer=~"$ai_consumer",
    cluster=~"$cluster",
    ai_model=~"$ai_model"
  }[2m])
)
and
sum by (ai_model) (
  irate(route_upstream_model_consumer_metric_llm_duration_count{
    ai_consumer=~"$ai_consumer",
    cluster=~"$cluster",
    ai_model=~"$ai_model"
  }[2m])
) > 0

label_replace(
  label_replace(
    histogram_quantile(0.95,
      sum by (ai_route, ai_cluster, ai_consumer, le) (
        irate(route_upstream_model_consumer_metric_llm_first_token_duration_ms_bucket{ai_consumer=~"$ai_consumer", cluster=~"$cluster", ai_model=~"$ai_model"}[5m])
      )
    ),
    "ai_route", "$1", "ai_route", "ai-route-(.+)\\.internal"
  ),
  "ai_cluster", "$1", "ai_cluster", "outbound\\|\\d+\\|\\|llm-(.+)\\.internal\\..+"
)

histogram_quantile(0.99,
  sum by (model_name, le) (
    irate(vllm:time_to_first_token_seconds_bucket{app="大模型推理监控"
  }[5m])
  )
)or histogram_quantile(0.99,
  sum by (model_name, le) (
    irate(sglang:time_to_first_token_seconds_bucket{app="大模型推理监控"}[5m])
  )
)

histogram_quantile(0.95,
  sum by (model_name, le) (
    irate(vllm:time_to_first_token_seconds_bucket{app="大模型推理监控"
  }[5m])
  )
)or histogram_quantile(0.95,
  sum by (model_name, le) (
    irate(sglang:time_to_first_token_seconds_bucket{app="大模型推理监控"}[5m])
  )
)
